{
  "themes": {
    "shadow": {
      "2xs": {
        "$extensions": {
          "com.clossys.css": {
            "raw": "0 1px rgb(0 0 0 / 0.05)"
          }
        },
        "$type": "shadow",
        "$value": "0 1px rgb(0 0 0 / 0.05)"
      },
      "xs": {
        "$extensions": {
          "com.clossys.css": {
            "raw": "0 1px 2px 0 rgb(0 0 0 / 0.05)"
          }
        },
        "$type": "shadow",
        "$value": "0 1px 2px 0 rgb(0 0 0 / 0.05)"
      },
      "sm": {
        "$extensions": {
          "com.clossys.css": {
            "raw": "0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1)"
          }
        },
        "$type": "shadow",
        "$value": "0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1)"
      },
      "md": {
        "$extensions": {
          "com.clossys.css": {
            "raw": "0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1)"
          }
        },
        "$type": "shadow",
        "$value": "0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1)"
      },
      "lg": {
        "$extensions": {
          "com.clossys.css": {
            "raw": "0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1)"
          }
        },
        "$type": "shadow",
        "$value": "0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1)"
      },
      "xl": {
        "$extensions": {
          "com.clossys.css": {
            "raw": "0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1)"
          }
        },
        "$type": "shadow",
        "$value": "0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1)"
      },
      "2xl": {
        "$extensions": {
          "com.clossys.css": {
            "raw": "0 25px 50px -12px rgb(0 0 0 / 0.25)"
          }
        },
        "$type": "shadow",
        "$value": "0 25px 50px -12px rgb(0 0 0 / 0.25)"
      }
    }
  }
}
